import re
import json
import logging


def parse_json_string_to_dict(json_string: str) -> dict:
    """
    Parses JSON string to dictionary.

    This function handles JSON strings with various formats, including those with single quotes,
    missing quotes, and strings with spaces. It ensures that the JSON string is properly formatted
    before converting it to a dictionary.

    :param json_string: JSON string to be parsed
    :type json_string: str
    :return: Dictionary representation of the JSON string
    :rtype: dict

    Examples:
        valid_json_string = '{"key": "value", "number": 123, "boolean": true, "null_value": null,
                              "long": "hej hi2 smth"}'
        json_string_with_single_quotes = "{'key': 'value', 'number': 123, 'boolean': true, 'null_value': null,
                                           'long': 'hej hi2 smth'}"
        json_string_without_quotes = "{key: value, number: 123, boolean: true, null_value: null, long: hej hi2 smth}"
        json_string_without_spaces = "{key:value,number:123,boolean:true,null_value:null,long: hej hi2 smth}"
        json_string_with_array_mixed = '{"key": "value", "array": [1, 2, 3], "nested_array": [{"id": 1}, {"id": 2}],
                                         param:[value1, value2], long: hej hi2 smth}'
    """
    try:
        return json.loads(json_string)
    except json.JSONDecodeError:
        logging.debug("JSON string is not valid. Trying to fix it.")

    logging.debug(f"String before parsing: {json_string}")
    logging.debug("Try to just replace ' with \"")
    logging.debug(f"String after simple replace: {json_string}")

    first_try_json_string = json_string.replace("'", "\"")
    try:
        return json.loads(first_try_json_string)
    except json.JSONDecodeError:
        logging.debug("JSON string is still not valid. Trying to fix it further.")

    json_string = json_string.replace("'", "")
    json_string = json_string.replace('"', "")
    json_string = re.sub(r'(\w+)', r'"\1"', json_string)

    matches = re.findall(r' "([\w\s\d<>"]+)"', json_string)  # Find all strings with spaces
    for match in matches:
        replaced = match.replace('"', '')
        json_string = re.sub(fr'"{match}"', fr'"{replaced}"', json_string)

    json_string = re.sub(r'"(\d+)"', r'\1', json_string)  # Keep numbers as numbers
    json_string = re.sub(r'":\s*"(true|false|null)"', r'": \1', json_string)  # Keep booleans and null as is
    logging.debug(f"String after parsing: {json_string}")
    logging.debug("Loading JSON string")
    data = json.loads(json_string)
    return data
